/**
 * Unified modifier pipeline — TD-FROZEN types (+ one pure reference fold). Implementation: GAME-RUN.
 *
 * EVERY gameplay number that can be changed by something goes through ONE call:
 *   `run.mod(hook, machineId, base, query?)`            (`MachineBase.mod(hook, base)` wraps it)
 * Sources of change — charms, tycoon upgrades, buffs/debuffs, totems, nightly events, collateral,
 * character perks, prestige/meta nodes, contracts, boss/ante rules — are all reduced to declarative
 * {@link ModEffect}s (data, serialisable, generated by templates) plus optional code via `modify`.
 *
 * Fold order (exact, deterministic, identical on every peer):
 *   1. `set` — the highest-priority `set` replaces the base.
 *   2. `v = (v + Σ add) × (1 + Σ inc) × Π mult`
 *        add  = flat points ("+1 luck", "+5 coins")
 *        inc  = additive percentage group, GDD "(A)": +0.15 means +15 %, summed before multiplying
 *        mult = multiplicative factor, GDD "(M)": ×1.5
 *   3. `v = max(v, Σ…min)` / `min(v, …max)` floors and caps from effects.
 *   4. Hook clamp from {@link MOD_HOOKS}.
 * Stack scaling (buffs): `add`/`inc` contribute `value × stacks`, `mult` contributes `value ^ stacks`
 * unless `perStack === false`. Upgrades resolve their level-dependent value before producing the effect.
 */
import type { GameMode, InstanceId, MachineId, PlayerId, V3, ZoneId } from '@/core/types';
import type { MachineCategory } from '@/machines/_base/types';

/** Hooks every system understands. Defaults/clamps live in {@link MOD_HOOKS}. */
export type CoreModHook =
  // ── economy (TECH_SPEC §2.13) ──
  | 'bet.costMult'    // ×coin cost of a bet (nominal bet for payouts unchanged)
  | 'payout.mult'     // ×gross winnings when gross>0
  | 'payout.flat'     // +coins on any win
  | 'loss.refund'     // fraction of bet refunded when gross==0
  | 'luck'            // integer luck points (each machine defines the effect)
  | 'jackpot.mult'    // ×jackpot pool claims
  | 'reroll'          // free re-spins/redraws per round where supported
  | 'deposit.bonus'   // fraction added to debt deposits
  | 'shop.discount'   // fraction off charm prices
  | 'time.bonus'      // seconds added to the shift clock
  // ── tycoon / pacing (ADDENDUM 1) ──
  | 'speed.mult'      // ×machine animation / resolve durations (<1 = faster)
  | 'bet.maxMult'     // ×max bet (Cap track)
  | 'lines.extra'     // + paylines / reels / boxes / tickets per round
  | 'seats.extra'     // + usable seats at a table
  | 'autoplay'        // >0 enables auto-play on the machine
  | 'heat.gain'       // ×win-streak heat gain
  | 'income.mult'     // ×staff / idle income
  | 'upgrade.costMult'// ×tycoon upgrade prices
  | 'interest.add'    // +fraction interest on deposits at settle
  | 'coin.magnet'     // +metres: tray coins fly to you
  // ── quota / shift (ADDENDUM 1) ──
  | 'quota.mult'      // ×quota amount
  | 'quota.add'       // +coins on the quota
  | 'overshoot.mult'  // ×overshoot bonus rewards
  // ── horror / body (ADDENDA 1, 8) ──
  | 'dread.add'       // +points on the 0..100 dread meter
  | 'player.moveSpeed'   // ×walk/sprint speed
  | 'player.actionSpeed' // ×hand-action speed (hand collateral → slower)
  | 'player.vision'      // 1 = full; porcelain eye lowers it (post vignette)
  | 'player.hearing'     // 1 = full; porcelain ear lowers it (audio muffle)
  | 'player.voice';      // 1 = full; porcelain mouth lowers it (garbled chat/voice)

/**
 * `m.<machineId>.<name>` — machine-specific (documented in the machine catalogue);
 * `x.<name>` — any other game-wide custom hook (charm/boss specials, e.g. 'x.tilt.grace').
 */
export type ModHook = CoreModHook | `m.${string}` | `x.${string}`;

export interface ModHookMeta {
  /** Value a fold starts from when the caller passes no base; also the neutral element. */
  def: number;
  min: number; max: number;
  /** Rounding after clamp: 'int' for counts (luck, reroll, lines). */
  round?: 'int';
}
const INF = Infinity;
export const MOD_HOOKS: Record<CoreModHook, ModHookMeta> = {
  'bet.costMult': { def: 1, min: 0, max: 10 },
  'payout.mult': { def: 1, min: 0, max: 1000 },          // GDD §3.3 guard `(1+A)×M ≤ 1000`
  'payout.flat': { def: 0, min: 0, max: INF },
  'loss.refund': { def: 0, min: 0, max: 1 },
  'luck': { def: 0, min: -30, max: 30, round: 'int' },   // GDD §3.8.1 clamp (spec said −10..20)
  'jackpot.mult': { def: 1, min: 0, max: 100 },
  'reroll': { def: 0, min: 0, max: 20, round: 'int' },
  'deposit.bonus': { def: 0, min: 0, max: 1 },
  'shop.discount': { def: 0, min: 0, max: 0.9 },
  'time.bonus': { def: 0, min: 0, max: 600 },
  'speed.mult': { def: 1, min: 0.25, max: 2 },
  'bet.maxMult': { def: 1, min: 0.1, max: 1e12 },
  'lines.extra': { def: 0, min: 0, max: 50, round: 'int' },
  'seats.extra': { def: 0, min: 0, max: 8, round: 'int' },
  'autoplay': { def: 0, min: 0, max: 1, round: 'int' },
  'heat.gain': { def: 1, min: 0, max: 10 },
  'income.mult': { def: 1, min: 0, max: 1e12 },
  'upgrade.costMult': { def: 1, min: 0.05, max: 10 },
  'interest.add': { def: 0, min: 0, max: 1 },
  'coin.magnet': { def: 0, min: 0, max: 30 },
  'quota.mult': { def: 1, min: 0.1, max: 10 },
  'quota.add': { def: 0, min: -INF, max: INF },
  'overshoot.mult': { def: 1, min: 0, max: 10 },
  'dread.add': { def: 0, min: -100, max: 100 },
  'player.moveSpeed': { def: 1, min: 0.1, max: 3 },
  'player.actionSpeed': { def: 1, min: 0.25, max: 2 },
  'player.vision': { def: 1, min: 0, max: 1 },
  'player.hearing': { def: 1, min: 0, max: 1 },
  'player.voice': { def: 1, min: 0, max: 1 },
};
const FREE_HOOK: ModHookMeta = { def: 0, min: -INF, max: INF };
/** Meta for any hook; machine/custom hooks (`m.*`, `x.*`) are unclamped with neutral 0 unless the caller supplies a base. */
export function modHookMeta(hook: ModHook): ModHookMeta {
  return (MOD_HOOKS as Record<string, ModHookMeta>)[hook] ?? FREE_HOOK;
}

// ── effects ─────────────────────────────────────────────────────────────────────────────────────
export type ModOp = 'add' | 'inc' | 'mult' | 'set' | 'min' | 'max';

/** Which machines / players / places an effect applies to. All present fields must match (AND). */
export interface ModScope {
  machines?: MachineId[];
  categories?: MachineCategory[];
  /** Machine `tags` (suits, families, 'table', 'solo' …). */
  tags?: string[];
  zones?: ZoneId[];
  instances?: InstanceId[];
  modes?: GameMode[];
  /** Only these players (0 = anyone). */
  players?: PlayerId[];
  /** World-space disc: applies to machine instances / players inside it (Totems). */
  radius?: { center: V3; r: number };
}

export interface ModEffect {
  hook: ModHook;
  op: ModOp;
  value: number;
  scope?: ModScope;
  /** Buff stacks scale the value (default true). */
  perStack?: boolean;
  /** Higher wins for `set`; ties by source order. Default 0. */
  priority?: number;
  /** Optional i18n key for the pause-menu ledger line; default auto-generated from hook+value. */
  label?: string;
}

export type ModSourceKind =
  | 'charm' | 'upgrade' | 'buff' | 'totem' | 'event' | 'collateral' | 'character' | 'prestige'
  | 'contract' | 'house' | 'rule' | 'machine' | 'debug';

/** One thing currently contributing. `stacks` is applied per {@link ModEffect.perStack}. */
export interface ModSource {
  kind: ModSourceKind;
  id: string;
  /** Who it belongs to: a player id, 0 = team/pit, or the instance it sits on. */
  owner: PlayerId | InstanceId;
  stacks?: number;
  effects: readonly ModEffect[];
  /** Acquisition order (charm fold order). */
  order?: number;
  /** Code-defined escape hatch for odd rules (runs after the declarative fold of this source's hook). */
  modify?(hook: ModHook, machineId: MachineId, value: number, q: ModQuery): number;
}

/** Context of a `mod()` call. All optional; `pid` defaults to the local player. */
export interface ModQuery {
  pid?: PlayerId;
  /** Machine instance in play (enables instance-scoped upgrades & radius totems). */
  instance?: InstanceId;
  /** World position for radius scopes (defaults to the instance position, else the player's). */
  pos?: V3;
  /** Extra numeric context a source may condition on (bet size, streak, heat…). */
  ctx?: Record<string, number>;
}

/** A source of {@link ModSource}s (charms, tycoon, buffs, totems … each implement one). */
export interface ModProvider {
  readonly kind: ModSourceKind;
  /** Append the sources active for this query. Called on hot paths: no allocation beyond `out`. */
  collect(q: ModQuery, out: ModSource[]): void;
}

export interface ModBreakdownStep {
  source: { kind: ModSourceKind; id: string; owner: PlayerId | InstanceId };
  op: ModOp; value: number; stacks: number;
  before: number; after: number;
}
export interface ModBreakdown {
  hook: ModHook; machineId: MachineId; base: number; result: number; clamped: boolean;
  steps: ModBreakdownStep[];
}

export interface ModifierApi {
  /** Fold `base` through every active source. Cached per (hook, machine, query) until `touch()`. */
  mod(hook: ModHook, machineId: MachineId, base: number, q?: ModQuery): number;
  /** Same as `mod` but returns the ordered contributions (pause ledger, tooltips, debug). */
  explain(hook: ModHook, machineId: MachineId, base: number, q?: ModQuery): ModBreakdown;
  register(p: ModProvider): () => void;
  /** Invalidate caches — providers call it whenever their state changes. */
  touch(): void;
  readonly revision: number;
}

/** Whether an effect's scope accepts the given machine context. Reference implementation of scope matching. */
export function scopeMatches(
  s: ModScope | undefined,
  m: { machineId: MachineId; category?: MachineCategory; tags?: readonly string[]; zone?: ZoneId; instance?: InstanceId; mode?: GameMode; pid?: PlayerId; pos?: V3 },
): boolean {
  if (!s) return true;
  if (s.machines && !s.machines.includes(m.machineId)) return false;
  if (s.categories && (!m.category || !s.categories.includes(m.category))) return false;
  if (s.tags && !(m.tags && s.tags.some((t) => m.tags!.includes(t)))) return false;
  if (s.zones && (!m.zone || !s.zones.includes(m.zone))) return false;
  if (s.instances && (!m.instance || !s.instances.includes(m.instance))) return false;
  if (s.modes && (!m.mode || !s.modes.includes(m.mode))) return false;
  if (s.players && !s.players.includes(0) && (m.pid === undefined || !s.players.includes(m.pid))) return false;
  if (s.radius) {
    if (!m.pos) return false;
    const dx = m.pos[0] - s.radius.center[0], dz = m.pos[2] - s.radius.center[2], dy = m.pos[1] - s.radius.center[1];
    if (dx * dx + dy * dy + dz * dz > s.radius.r * s.radius.r) return false;
  }
  return true;
}

/**
 * Reference fold — the exact arithmetic every implementation must reproduce (see header).
 * `effs` are already scope-filtered and stack-scaled by the caller (use {@link stackedValue}).
 */
export function foldEffects(hook: ModHook, base: number, effs: ReadonlyArray<{ op: ModOp; value: number; priority?: number }>): number {
  let add = 0, inc = 0, mult = 1, floor = -Infinity, cap = Infinity;
  let setV: number | undefined, setP = -Infinity;
  for (const e of effs) {
    switch (e.op) {
      case 'add': add += e.value; break;
      case 'inc': inc += e.value; break;
      case 'mult': mult *= e.value; break;
      case 'min': floor = Math.max(floor, e.value); break;
      case 'max': cap = Math.min(cap, e.value); break;
      case 'set': if ((e.priority ?? 0) >= setP) { setP = e.priority ?? 0; setV = e.value; } break;
    }
  }
  let v = setV ?? base;
  v = (v + add) * (1 + inc) * mult;
  if (floor > -Infinity) v = Math.max(v, floor);
  if (cap < Infinity) v = Math.min(v, cap);
  const m = modHookMeta(hook);
  v = Math.min(m.max, Math.max(m.min, v));
  return m.round === 'int' ? Math.round(v) : v;
}

/** Stack-scaled value of an effect (`add`/`inc` linear in stacks, `mult` exponential). */
export function stackedValue(e: ModEffect, stacks: number): number {
  if (e.perStack === false || stacks === 1) return e.value;
  return e.op === 'mult' ? Math.pow(e.value, stacks) : e.op === 'add' || e.op === 'inc' ? e.value * stacks : e.value;
}
